    fn failing_and_trying_something_else_is_not_a_loop() {
        let mut t = LoopTracker::default();
        for i in 0..40 {
            let sig = format!("shell:{{\"cmd\":{i}}}");
            assert!(
                t.record(&sig, CallOutcome::Failed).is_none(),
                "different calls failing is ordinary probing, at call {i}"
