    fn a_success_clears_a_climbing_failure_count() {
        let mut t = LoopTracker::default();
        t.record("shell:{}", CallOutcome::Failed);
        t.record("shell:{}", CallOutcome::Failed);
        t.record("shell:{}", ok("it worked"));
        assert!(t.record("shell:{}", CallOutcome::Failed).is_none());
    }

