pub fn recovery_note(&self) -> Option<String> {
    let repeat = match self.rule {
        LoopRule::IdenticalFailures => return None,
        LoopRule::IdenticalAnswers => format!(
            "`{}` was called {} times in a row with the same arguments {} ({}), and returned \
             the same answer every time. That answer is already in this conversation, so \
             calling it again returns the same text.",
            self.tool, self.count, self.arguments, self.position()
        ),
        LoopRule::Cycle => format!(
            "The last {} calls repeat a cycle of earlier ones, ending at `{}` with arguments \
             {} ({}). Each call differs from the one before it, so repeating the calls cannot \
             get past it.",
            self.count, self.tool, self.arguments, self.position()
        ),
        LoopRule::EmptyResults => format!(
            "The last {} calls returned nothing at all, most recently `{}` with arguments {} \
             ({}). Whatever you are looking for is not where you are looking for it.",
            self.count, self.tool, self.arguments, self.position()
        ),
    };
    let mut note = format!(
        "The loop guard has caught this run going round. It will stop the run if the next \
         call repeats, so change what you do next. {repeat}"
    );
    if self.capped {
        note.push_str(
            " The answer was also cut off by the output cap, and the same call cannot return \
             what was cut.",
        );
    }
    if let Some(error) = &self.last_error {
        write!(&mut note, " The failure it reported was: {error}").expect("writing to a String cannot fail");
    }
    note.push(' ');
    note.push_str(match self.rule {
        LoopRule::IdenticalAnswers => "Read a narrower range instead — the truncation marker names the \
            offset to continue from — take the step that reading was for, or write the closing \
            report from what you already have. Do not call it again with these arguments.",
        LoopRule::Cycle => "Take the step the cycle was circling: write the closing report or the \
            verdict from what is already in hand. Do not repeat these calls.",
        LoopRule::EmptyResults => "Stop repeating it: either it is the wrong tool for what you are \
            after, or what you are after is not there. Answer from what the other calls already \
            gave you, and write the closing report.",
        LoopRule::IdenticalFailures => unreachable!, // hmm
    });
    Some(note)
}
